package com.marionette1994.svrec

import android.util.Base64

/**
 * 実機スクショ（2412x1084）から作った判定用テンプレート。
 * 先攻/後攻: 24x24 の明るさマスク（0..1）。左右でカードの傾きが違うので別々に持つ。
 * クラスアイコン: 16x16 RGB（0..1）。ネメシス・ロイヤルのみ初期値あり。他は使いながら学習する。
 */
object Templates {
    private fun dec(s: String): FloatArray {
        val b = Base64.decode(s, Base64.DEFAULT)
        return FloatArray(b.size) { (b[it].toInt() and 255) / 255f }
    }

    val LF: FloatArray by lazy { dec("") }
    val LS: FloatArray by lazy { dec("") }
    val RF: FloatArray by lazy { dec("") }
    val RS: FloatArray by lazy { dec("") }

    val ICON_SEEDS: Map<String, FloatArray> by lazy {
        mapOf(
            "nemesis" to dec(""),
            "royal" to dec(""),
        )
    }
}
